import json,statistics
from pathlib import Path
P=Path(__file__).resolve().parent;r=json.loads((P/'results.json').read_text(encoding='utf-8'));assert r['status']=='PASS' and len(r['rows'])==15;rows=r['rows'];seeds=(1234,42,2025)
lines=['# U1 v3.2: 5 fold × 3 seed trên inner-validation','', '**Tiến độ plan:** Đã hoàn tất và kiểm tra 15 lượt validation; còn đánh giá outer-test/ablation theo protocol cố định và xác minh nguồn tác giả.','', 'Các lượt seed 1234 đã có trước; thêm seed 42 và 2025 trên fold 1–4, cùng model/negative-bank seed, horizon 650 và bundle selection. Đây là validation đã dùng chọn checkpoint và phát triển pipeline, không phải 15 test độc lập, không phải kết quả tương đương paper. Một phần seed 1234 chạy Linux/Colab; các lượt mới chạy Windows CPU.','', '| Fold | Seed 1234 | Seed 42 | Seed 2025 | Product prior | Disease prior |','|---:|---:|---:|---:|---:|---:|']
for fold in range(5):
 a={x['seed']:x for x in rows if x['fold']==fold};lines.append('| %d | %.4f | %.4f | %.4f | %.4f | %.4f |'%(fold,a[1234]['best']['macro_f1'],a[42]['best']['macro_f1'],a[2025]['best']['macro_f1'],a[1234]['product']['macro_f1'],a[1234]['disease']['macro_f1']))
lines+=['','Bảng ghi macro-F1 của checkpoint tốt nhất trên chính validation; prior được fit từ train và cố định theo fold. Mỗi lượt đánh giá 65 lần, nên best là thống kê có thiên lệch lựa chọn.','', '| Seed | Best macro-F1: mean ± SD theo 5 fold | Mean macro-F1 tại epoch 650 |','|---:|---:|---:|']
for s in seeds:
 q=r['summary'][str(s)];lines.append('| %d | %.4f ± %.4f | %.4f |'%(s,q['best_macro_mean_over_folds'],q['best_macro_sd_over_folds'],q['final_macro_mean_over_folds']))
mean=lambda side,k:statistics.mean(x[side][k] for x in rows)
lines+=['',f"Trung bình mô tả trên 15 ô: U1 best macro {mean('best','macro_f1'):.4f}, micro {mean('best','micro_f1'):.4f}, any-hit {mean('best','any_hit'):.4f}; product prior tương ứng {mean('product','macro_f1'):.4f}, {mean('product','micro_f1'):.4f}, {mean('product','any_hit'):.4f}; disease prior {mean('disease','macro_f1'):.4f}, {mean('disease','micro_f1'):.4f}, {mean('disease','any_hit'):.4f}. Các ô chia sẻ dữ liệu giữa fold/seed, không dùng làm 15 quan sát độc lập.",'', 'Kết quả `results.json` chứa đầy đủ 15 lượt, metric từng lớp và hash; `score.py` đối chiếu manifest, nhãn và pair validation, tính lại metric bằng scikit-learn. Macro được định nghĩa argmax-onehot so với truth multi-hot đủ 5 loại; chưa xác minh tương đương Top-1 F1 paper. Các fold đã tham gia quá trình phát triển và một outer-test fold0 từng được xem; không coi đây là thử nghiệm mù hay chứng minh tái hiện 0,8600.','', 'Còn thiếu: nguồn và fold tác giả, công thức metric gốc, đánh giá outer-test/ablation 5 fold × 3 seed theo protocol cố định và refit được kiểm tra. Kết quả này không thay thế các hạng mục đó.']
with (P/'REPORT.md').open('x',encoding='utf-8') as f:f.write('\n'.join(lines)+'\n')
print('report written')
